(7702601, 1264355, 67258, '<td valign="top">An appealing composition and mono conversion.  the tree is, indeed, majestic!</td>', 'An appealing composition and mono conversion.  the tree is, indeed, majestic!', '2021-10-05 15:12:53.000000', NULL, 1),
(7702602, 1264610, 67258, '<td valign="top">Excellent title to a pleasingly understated natural history photograph.</td>', 'Excellent title to a pleasingly understated natural history photograph.', '2021-10-05 15:13:25.000000', NULL, 1),
(7702605, 1264453, 67258, '<td valign="top">Cracking composition.</td>', 'Cracking composition.', '2021-10-05 15:16:18.000000', NULL, 1),
(7702606, 1264649, 67258, '<td valign="top">What a fab photo. The only thing that would improve it is a sense of fun, a happy, laughing face.  I do urge you to try this again, as the idea is excellent, and your technicals work - just need your young model to cooperate more!</td>', 'What a fab photo. The only thing that would improve it is a sense of fun, a happy, laughing face.  I do urge you to try this again, as the idea is excellent, and your technicals work - just need your young model to cooperate more!', '2021-10-05 15:17:45.000000', NULL, 1),
(7702608, 1264339, 67258, '<td valign="top">Dear God, that is something I have never seen!  Definitely a photo of the moment, and I am curious as to the outcome. In terms of photographic merit it is a 6, but in terms of photo uniqueness, a 10 - a 7 from me, but this needs wider exposure (forgive the unintended photographic pun) in natural history circles.</td>', 'Dear God, that is something I have never seen!  Definitely a photo of the moment, and I am curious as to the outcome. In terms of photographic merit it is a 6, but in terms of photo uniqueness, a 10 - a 7 from me, but this needs wider exposure (forgive the unintended photographic pun) in natural history circles.', '2021-10-05 15:19:49.000000', NULL, 1),
(7702609, 1264596, 67258, '<td valign="top">I had no idea!!!! Fascinating, and I have learned something new.</td>', 'I had no idea!!!! Fascinating, and I have learned something new.', '2021-10-05 15:20:20.000000', NULL, 1),
(7702611, 1264597, 67258, '<td valign="top">How fascinating - excellent example of urban decay.</td>', 'How fascinating - excellent example of urban decay.', '2021-10-05 15:22:26.000000', NULL, 1),
(7702612, 1264594, 67258, '<td valign="top">Love this - egrets have made their way to the UK in the last couple of decades, but they are still an unusual bird to see close.</td>', 'Love this - egrets have made their way to the UK in the last couple of decades, but they are still an unusual bird to see close.', '2021-10-05 15:23:12.000000', NULL, 1),
