(7702616, 1264648, 67258, '<td valign="top">Excellent use of forced perspective.  Shame the noise is so marked - have you tried Topaz deNoise?  definitely worth exploring further.</td>', 'Excellent use of forced perspective.  Shame the noise is so marked - have you tried Topaz deNoise?  definitely worth exploring further.', '2021-10-05 15:26:14.000000', NULL, 1),
(7702617, 1264527, 67258, '<td valign="top">Whilst your concept is fine, your lighting has let you down.</td>', 'Whilst your concept is fine, your lighting has let you down.', '2021-10-05 15:27:11.000000', NULL, 1),
