(7702620, 1264605, 67258, '<td valign="top">Oh yes, I like this very much, lots of depth, both literally, and in terms of patterns and composition.</td>', 'Oh yes, I like this very much, lots of depth, both literally, and in terms of patterns and composition.', '2021-10-05 15:29:05.000000', NULL, 1),
(7702621, 1264589, 67258, '<td valign="top">I haven''t got a clue what is going on here, but the photo is definitely making my brain try and work !  a good example of candid photography.</td>', 'I haven''t got a clue what is going on here, but the photo is definitely making my brain try and work !  a good example of candid photography.', '2021-10-05 15:30:21.000000', NULL, 1),
